(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.PlaytestDecisionTask=api;})(typeof globalThis==='undefined'?this:globalThis,function(){
'use strict';
const L=(zh,en)=>({zh,en}),copy=x=>JSON.parse(JSON.stringify(x));
const task={id:'business-model-decisions-v1',replacesRoundId:'repair-mapping',title:L('店铺助手：资料、结果与参数变化','Shop assistant: data, results and parameter changes'),
 goal:L('能分清模型使用的资料和产生的结果，并用参数是否改变判断训练或推理。','Distinguish model data from its results and use parameter changes to identify training or inference.'),
 scenario:L('店铺记录了过去一周每天实际卖出的杯数，助手据此估计明天需要备多少杯，店长再安排备料。请完成两项数据判断，再判断后台两次工作。','A shop records actual cups sold each day last week. Its assistant estimates tomorrow’s demand, and the manager plans supplies. Make two data decisions, then judge two background jobs.'),
 foundation:L('输入是模型拿来处理的资料，输出是模型产生的结果。训练根据样本学习并调整参数；推理使用已有参数处理输入。新工单或新文字本身不代表发生训练。','Inputs are data the model processes; outputs are results it produces. Training learns from examples and adjusts parameters; inference uses existing parameters. A new ticket or new text alone does not establish training.'),
 operation:L('为每个问题点击一个判断；不输入英文代码。出错后只修改需要订正的项。','Select one judgment per question; no code entry is needed. After feedback, revise only the items that need correction.'),
 questions:[
 {id:'data-in',legacyField:'input',prompt:L('哪份资料交给模型，帮助它估计明天的需求？','Which information goes to the model to help estimate tomorrow’s demand?'),options:[{id:'observations',text:L('过去一周实际售出杯数','Actual cups sold last week')},{id:'estimate',text:L('模型对明天杯数的估计','The model’s estimate for tomorrow')}],expected:'observations',legacyValue:'history',knowledgeIds:['1.1-lesson-2'],feedback:L('实际售出杯数是已经观测到、交给模型处理的资料，属于输入。明日估计尚未实际发生。','Observed past sales are data supplied to the model: inputs. Tomorrow’s estimate is not an observed outcome.')},
 {id:'data-out',legacyField:'output',prompt:L('哪项是模型产生、供店长安排备料的结果？','Which result does the model produce for the manager’s supply planning?'),options:[{id:'estimate',text:L('明天需要杯数的估计','Estimated cups needed tomorrow')},{id:'observations',text:L('过去一周实际售出杯数','Actual cups sold last week')}],expected:'estimate',legacyValue:'forecast',knowledgeIds:['1.1-lesson-2'],feedback:L('明日杯数是模型产生的估计，属于输出；店长如何安排备料是使用结果作出的后续行动。','Estimated demand is the model’s output. The manager’s supply decision is a downstream action using that result.')},
 {id:'job-a',legacyField:'eventA',prompt:L('A：助手读取一张新工单，使用已保存且未修改的权重生成回复。这次发生了什么？','A: the assistant reads a new ticket and generates a reply using saved, unchanged weights. What happened?'),options:[{id:'fit',text:L('训练：这次从样本学习并调整参数','Training: this job learns from examples and adjusts parameters')},{id:'run',text:L('推理：这次使用已有参数','Inference: this job uses existing parameters')},{id:'unknown',text:L('记录不足，无法区分','The record is insufficient to distinguish')}],expected:'run',legacyValue:'infer',knowledgeIds:['1.1-lesson-4'],feedback:L('A 没有更新参数，使用已有模型回答新工单，属于推理。新工单和新回复不等于参数学习。','A does not update parameters and uses the existing model on a new ticket: inference. New tickets and replies are not parameter learning.')},
 {id:'job-b',legacyField:'eventB',prompt:L('B：后台把样本的预测与已知实际结果比较，将误差用于调整权重并保存新参数。这次发生了什么？','B: a background job compares predictions with known example outcomes, uses errors to adjust weights and saves new parameters. What happened?'),options:[{id:'run',text:L('推理：只使用已有参数','Inference: only existing parameters are used')},{id:'unknown',text:L('记录不足，无法区分','The record is insufficient to distinguish')},{id:'fit',text:L('训练：根据样本改变参数','Training: parameters change through examples')}],expected:'fit',legacyValue:'train',knowledgeIds:['1.1-lesson-3'],feedback:L('B 根据样本误差调整参数，改变了模型，属于训练；这不只是用原模型生成一次结果。','B adjusts parameters from example errors and changes the model: training, rather than simply generating a result with unchanged parameters.')}
 ],access:{reuseCurrentKnowledgeProgress:true,requiresReplay22Foundations:false,knowledgeReviewAlwaysAvailable:true},
 completion:L('本次业务判断完成。仍需完成本节其余活动与整章正式测验；不因这四项通过就宣称整章已掌握。','These business decisions are complete. Finish the section’s remaining activities and formal chapter assessment; four judgments do not establish chapter mastery.')};
const legacyOptions={input:{history:'observations',forecast:'estimate'},output:{forecast:'estimate',history:'observations'},eventA:{infer:'run',train:'fit',unresolved:'unknown'},eventB:{train:'fit',infer:'run',unresolved:'unknown'}};
function begin(oldDraft={}){return {version:1,taskId:task.id,choices:{},helpSeen:false,oldDraft:copy(oldDraft)};}
function beginLegacy(draft={}){const s=begin(draft);s.helpSeen=true;for(const q of task.questions){const option=legacyOptions[q.legacyField][draft.values?.[q.legacyField]];if(option)s.choices[q.id]=option;}return s;}
function legacyFieldFor(id){const q=task.questions.find(q=>q.id===id);if(!q)throw Error('Unknown decision question');return q.legacyField;}
function legacyValueFor(id,option){const q=task.questions.find(q=>q.id===id);if(!q||!q.options.some(o=>o.id===option))throw Error('Unknown decision option');return Object.entries(legacyOptions[q.legacyField]).find(([,v])=>v===option)?.[0]||'unresolved';}
function choose(state,id,option){const q=task.questions.find(q=>q.id===id);if(!q||!q.options.some(o=>o.id===option))throw Error('Unknown decision option');const next=copy(state);next.choices[id]=option;return next;}
function evaluate(state){
 if(state?.taskId!==task.id||state.version!==1)throw Error('Unknown decision task');
 const checks=task.questions.map(q=>{const selected=state.choices[q.id],complete=q.options.some(o=>o.id===selected),correct=complete&&selected===q.expected;
  return {id:q.id,label:q.prompt,complete,correct,message:!complete?L('请选择一个判断，也可先回看知识。','Choose a judgment, or revisit the knowledge first.'):correct?L('此项符合记录，保留当前判断。','This judgment agrees with the record; keep it.'):q.feedback,knowledgeIds:q.knowledgeIds};});
 const complete=checks.every(c=>c.complete),correct=complete&&checks.every(c=>c.correct),next=copy(state);
 if(checks.some(c=>c.complete&&!c.correct))next.helpSeen=true;
 const answer=complete?{values:Object.fromEntries(task.questions.map(q=>{const selected=state.choices[q.id];const pair=Object.entries(legacyOptions[q.legacyField]).find(([,value])=>value===selected);return [q.legacyField,pair?.[0]||'unresolved'];}))}:null;
 return {complete,correct,checks,state:next,legacyAnswer:answer,applicationCompleted:correct,independentEvidence:correct&&!next.helpSeen,requiresFormalAssessment:true};
}
const baselineShape={"id":"repair-mapping","type":"edit","prompt":{"zh":"本演练接线：history=过去销量，forecast=模型对明日的估计；模型接收history产生forecast。事件A以现有参数回复新工单；事件B用样本调整参数。错误登记：输入forecast、输出history、A为train、B为infer。用固定代码history/forecast/train/infer修复四槽。","en":"Exercise wiring: history=past sales and forecast=the model’s estimate for tomorrow; the model receives history and produces forecast. Event A answers a new ticket using existing parameters; event B adjusts parameters using examples. Faulty register: input forecast, output history, A train, B infer. Repair four slots with the exact codes history/forecast/train/infer."},"fields":[{"id":"input","label":{"zh":"模型输入槽","en":"Model input slot"},"expected":"history"},{"id":"output","label":{"zh":"模型输出槽","en":"Model output slot"},"expected":"forecast"},{"id":"eventA","label":{"zh":"事件A：参数未更新","en":"Event A: parameters unchanged"},"expected":"infer"},{"id":"eventB","label":{"zh":"事件B：样本调整参数","en":"Event B: examples adjust parameters"},"expected":"train"}]};
function legacyMatches(round){try{return JSON.stringify({id:round.id,type:round.type,prompt:round.prompt,fields:round.fields.map(f=>({id:f.id,label:f.label,expected:f.expected}))})===JSON.stringify(baselineShape);}catch{return false;}}
function visibleTask(){const t=copy(task);for(const q of t.questions){delete q.expected;delete q.legacyField;delete q.legacyValue;delete q.feedback;}delete t.replacesRoundId;return t;}
return {task,visibleTask,begin,beginLegacy,legacyFieldFor,legacyValueFor,choose,evaluate,legacyMatches};
});
